import{c as t,Q as o,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Seeing a number of benchmarks showing Opus is the best model for long-running work","description":"","frontmatter":{"url":"https://x.com/bcherny/status/2063792263067754658","title":"Seeing a number of benchmarks showing Opus is the best model for long-running work","author":"Boris Cherny","archived":"2026-06-08T00:00:00.000Z","handle":"@bcherny","published":"2026-06-08T00:00:00.000Z","stats":"2484 likes · 193 retweets · 2942 bookmarks · 391258 views","type":"note-tweet"},"headers":[],"relativePath":"research/tweets/2026-06-08-@bcherny-754658.md","filePath":"research/tweets/2026-06-08-@bcherny-754658.md","lastUpdated":1780990164000}'),n={name:"research/tweets/2026-06-08-@bcherny-754658.md"};function a(i,e,l,d,h,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="seeing-a-number-of-benchmarks-showing-opus-is-the-best-model-for-long-running-work-—-bcherny" tabindex="-1">Seeing a number of benchmarks showing Opus is the best model for long-running work — @bcherny <a class="header-anchor" href="#seeing-a-number-of-benchmarks-showing-opus-is-the-best-model-for-long-running-work-—-bcherny" aria-label="Permalink to &quot;Seeing a number of benchmarks showing Opus is the best model for long-running work — @bcherny&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/bcherny/status/2063792263067754658" target="_blank" rel="noreferrer">https://x.com/bcherny/status/2063792263067754658</a><strong>作者</strong>：Boris Cherny（@bcherny） <strong>發布日期</strong>：2026-06-08 <strong>收錄日期</strong>：2026-06-08 <strong>類型</strong>：Note Tweet <strong>統計</strong>：2484 likes · 193 retweets · 2942 bookmarks · 391258 views</p><p><strong>注意</strong>：note tweet 格式，fxtwitter API 僅能取得 intro，全文請至原始連結閱讀</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Seeing a number of benchmarks showing Opus is the best model for long-running work.</p><p>Five tips for running Opus autonomously for hours/days:</p><ol><li>Use auto mode for permissions, so Claude doesn&#39;t ask for approval</li><li>Use dynamic workflows, to have Claude orchestrate hundreds/thousands of agents to get a task done</li><li>Use /goal or /loop, to nudge Claude to keep going until it&#39;s done</li><li>Use Claude Code in the cloud, so you can close your laptop (easiest way is the desktop or mobile app)</li><li>Make sure Claude has a way to self-verify its work end to end: Claude in Chrome browser extension for web, iOS/Android sim MCP for mobile, a way to start the full web server or service for backend work</li></ol><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Claude Code 作者分享 5 個讓 Opus 長時間自主運行的關鍵技巧，涵蓋權限、編排、持續推進、雲端部署與自我驗證。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Auto 權限模式</strong>：啟用 auto mode 讓 Claude 無需頻繁請求人工審批，降低中斷頻率</li><li><strong>Dynamic workflows</strong>：讓 Claude 自主編排數百至數千個 sub-agents 完成複雜任務</li><li><strong>/goal 與 /loop 指令</strong>：持續推進直到任務完成，防止 Claude 中途停頓</li><li><strong>雲端部署</strong>：透過 desktop/mobile app 把工作推到雲端，關閉筆電後仍可繼續</li><li><strong>端對端自我驗證</strong>：Web 用 Chrome extension、行動端用 iOS/Android sim MCP、後端啟動完整服務自測</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Opus 模型（長時間任務 benchmark 表現最佳）</li><li>Dynamic workflows（編排規模：hundreds/thousands of agents）</li><li><code>/goal</code>、<code>/loop</code> 指令</li><li>Claude Code cloud mode（desktop/mobile app）</li><li>Chrome browser extension（Web 驗證）</li><li>iOS/Android simulator MCP（行動端驗證）</li><li>391,258 views · 2,942 bookmarks（高傳播，反映業界高度關注）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>Note Tweet 截斷限制</strong>：僅有 intro，全文可能含工具設定細節或實測數據，評分受限</li><li><strong>Dynamic workflows 成本未揭示</strong>：數百/數千 agents 並行的 token 費用對一般用戶可能是顯著障礙</li><li><strong>自我驗證需額外工具</strong>：Chrome extension 和 iOS sim MCP 需預先設定，不是開箱即用，門檻因情境而異</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>5 個 tips 均可直接對應 workspace 設定，作者身份（Claude Code 工程師）可信度高</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Dynamic workflows 規模化 + 端對端自我驗證是新概念，其餘 tips 已有共識</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>Note Tweet 只有 intro，無實測數據；來自官方開發者有公信力但缺獨立驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>5 點各對應具體場景（backend/web/mobile），技術方向清晰但細節需全文</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有長時間自主任務場景，跨領域通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.3/10</strong></td><td>9×0.3+7×0.2+5×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：核心是多步驟自主流程（dynamic workflows、編排數千 agents、端對端自我驗證），作者身份加持，高度 workspace 可行動性</p>',21)])])}const b=t(n,[["render",a]]);export{c as __pageData,b as default};
